def set_run_font(run, size=14, bold=False, italic=False):
    run.font.name = "Times New Roman"
    run._element.rPr.rFonts.set(qn("w:eastAsia"), "Times New Roman")
    run.font.size = Pt(size)
    run.bold = bold
    run.italic = italic


def add_author_block(doc):
    for text, style in AUTHOR_LINES:
        para = doc.add_paragraph()
        para.alignment = WD_ALIGN_PARAGRAPH.RIGHT
        para.paragraph_format.line_spacing = 1.0
        para.paragraph_format.space_after = Pt(0)
        run = para.add_run(text)
        set_run_font(run, bold=style["bold"], italic=style["italic"])


def add_body(doc, paragraphs):
    for text in paragraphs:
        para = doc.add_paragraph()
        para.alignment = WD_ALIGN_PARAGRAPH.JUSTIFY
        para.paragraph_format.line_spacing = 1.5
        para.paragraph_format.space_after = Pt(0)
        run = para.add_run(text)
        set_run_font(run)


def add_literature(doc, items):
    heading = doc.add_paragraph()
    heading.alignment = WD_ALIGN_PARAGRAPH.JUSTIFY
    heading.paragraph_format.line_spacing = 1.5
    heading.paragraph_format.space_after = Pt(0)
    run = heading.add_run("Список литературы")
    set_run_font(run)

    for item in items:
        para = doc.add_paragraph(style="List Paragraph")
        para.alignment = WD_ALIGN_PARAGRAPH.JUSTIFY
        para.paragraph_format.line_spacing = 1.5
        para.paragraph_format.space_after = Pt(0)
        run = para.add_run(item)
        set_run_font(run)


for article in ARTICLES:
    doc = Document()

    style = doc.styles["Normal"]
    style.font.name = "Times New Roman"
    style._element.rPr.rFonts.set(qn("w:eastAsia"), "Times New Roman")
    style.font.size = Pt(14)

    for section in doc.sections:
        section.top_margin = Cm(2)
        section.bottom_margin = Cm(2)
        section.left_margin = Cm(2)
        section.right_margin = Cm(2)

    title = doc.add_paragraph()
    title.alignment = WD_ALIGN_PARAGRAPH.CENTER
    title.paragraph_format.line_spacing = 1.5
    title.paragraph_format.space_after = Pt(0)
    title_run = title.add_run(article["title"].upper())
    set_run_font(title_run, bold=True)

    add_author_block(doc)
    doc.add_paragraph()
    add_body(doc, article["paragraphs"])
    add_literature(doc, article["literature"])

    doc.save(article["filename"])
